        String digest=LocalFiles.sha256(result);((ObjectNode)document.path("sources").get(0)).put("sha256",digest);((ObjectNode)document.path("evidence_links").get(0)).put("sha256",digest);((ObjectNode)document.path("evidence_links").get(1)).put("sha256",LocalFiles.sha256(path));
