    private void resealRepairAuthority(boolean authorityRaw)throws Exception {
        if(!authorityRaw)Json.MAPPER.writeValue(authorityPath.toFile(),authorityInput);authorityPin=LocalFiles.sha256(authorityPath);Path frozen=coverage.getParent().resolve("coverage-inputs");
        for(String name:List.of("authority.json","catalog.json","attestation.json")){Path original=root.resolve(name);if(Files.exists(original))Files.write(frozen.resolve(name),Files.readAllBytes(original));}
        ObjectNode pub=(ObjectNode)document.path("coverage_authority");pub.put("sha256",authorityPin);pub.set("catalog",authorityInput.path("catalog").deepCopy());for(var file:pub.path("artifacts"))((ObjectNode)file).put("sha256",LocalFiles.sha256(Path.of(file.path("path").asText())));if(authorityInput.hasNonNull("catalog"))((ObjectNode)document.path("inventory")).put("catalog_sha256",LocalFiles.sha256(root.resolve("catalog.json")));for(var row:document.path("oracle_trace"))if(row.path("independence").has("attestation_sha256"))((ObjectNode)row.path("independence")).put("attestation_sha256",LocalFiles.sha256(root.resolve("attestation.json")));save();
    }
