        reviewedAuthorityFixture(location.equals("catalog"));String canary="PUBLIC_SYNTHETIC_CVA_CONSUMER_CANARY_40812";Path file=location.equals("catalog")?root.resolve("catalog.json"):location.equals("attestation")?root.resolve("attestation.json"):authorityPath;
