        if(location.equals("catalog"))((ObjectNode)authorityInput.path("catalog")).put("sha256",LocalFiles.sha256(file));if(location.equals("attestation"))((ObjectNode)authorityInput.path("independent_attestations").get(0)).put("sha256",LocalFiles.sha256(file));resealRepairAuthority(location.equals("authority"));assertThatThrownBy(this::verifyAuthority).satisfies(error->{var trace=new java.io.StringWriter();error.printStackTrace(new java.io.PrintWriter(trace));assertThat(trace.toString()).doesNotContain(canary);assertThat(error.getMessage()).contains("COVERAGE_AUTHORITY_");assertThat(error.getCause()).isNull();assertThat(error.getSuppressed()).isEmpty();});
